-- NOM-052-SEMARNAT-2005 · Listado 2: residuos peligrosos por fuente no específica (claves NE).
insert into public.country_waste_listings (country_code, instrument_id, listing_code, listing_name, entry_key, description, hazard_codes, group_label, basel_code, verified, notes)
select 'MX', i.id, 'LISTADO-2', 'Listado 2 · Residuos peligrosos por fuente no específica', v.k, v.d, string_to_array(v.h, ','), 'Fuente no específica', v.bc, true, case when v.bc is not null then 'Equivalencia con Basilea inferida' end
from (values
('NE 01','RESIDUOS DEL MANEJO DE LA FIBRA DE ASBESTO PURO, INCLUYENDO POLVO, FIBRAS Y PRODUCTOS FACILMENTE DESMENUZABLES CON LA PRESION DE LA MANO (TODOS LOS RESIDUOS QUE CONTENGAN ASBESTO EL CUAL NO ESTE SUMERGIDO O FIJO EN UN AGLUTINANTE NATURAL O ARTIFICIAL)','Tt','A2050'),
('NE 02','TODAS LAS BOLSAS QUE HAYAN TENIDO CONTACTO CON LA FIBRA DE ASBESTO, ASI COMO LOS MATERIALES FILTRANTES PROVENIENTES DE LOS EQUIPOS DE CONTROL COMO SON: LOS FILTROS, MANGAS, RESPIRADORES PERSONALES Y OTROS, QUE NO HAYAN RECIBIDO UN TRATAMIENTO PARA ATRAPAR LA FIBRA EN UN AGLUTINANTE NATURAL O ARTIFICIAL','Tt','A2050'),
('NE 03','TODOS LOS RESIDUOS PROVENIENTES DE LOS PROCESOS DE MANUFACTURA CUYA MATERIA PRIMA SEA EL ASBESTO Y LA FIBRA SE ENCUENTRE EN FORMA LIBRE, POLVO O FACILMENTE DESMENUZABLE CON LA PRESION DE LA MANO','Tt','A2050'),
('NE 04','LODOS DE TRATAMIENTO DE AGUAS RESIDUALES DE APAGADO DE LAS OPERACIONES DE TRATAMIENTO TERMICO DE METALES DONDE LOS CIANUROS SON USADOS EN LOS PROCESOS','Tt','A4050'),
('NE 05','LODOS DE TRATAMIENTO DE AGUAS RESIDUALES DE OPERACIONES DE GALVANOPLASTIA EXCEPTO DE LOS SIGUIENTES PROCESOS: (1) ANODIZACION DE ALUMINIO EN ACIDO SULFURICO; (2) ESTAÑADO EN ACERO AL CARBON; (3) ZINCADO EN ACERO AL CARBON; (4) DEPOSITACION DE ALUMINIO O ZINC-ALUMINIO EN ACERO AL CARBON; (5) LIMPIEZA ASOCIADA CON ESTAÑADO, ZINCADO O ALUMINADO EN ACERO AL CARBON; Y (6) GRABADO QUIMICO Y ACABADO DE ALUMINIO DEPOSITADO EN ACERO AL CARBON','Tt','A1050'),
('NE 06','LODOS DE LOS BAÑOS DE ANODIZACION DEL ALUMINIO Y LODOS DE TRATAMIENTO DE AGUAS RESIDUALES DEL REVESTIMIENTO DE ALUMINIO POR CONVERSION QUIMICA','Tt',null),
('NE 07','RESIDUOS DE LOS BAÑOS EN OPERACIONES DE GALVANOPLASTIA DONDE LOS CIANUROS SON USADOS EN LOS PROCESOS','R,Tt','A4050'),
('NE 08','SOLUCIONES GASTADAS DE BAÑOS DE CIANURO DE LAS OPERACIONES DE GALVANOPLASTIA','R,Tt','A4050'),
('NE 09','SOLUCIONES GASTADAS DE LOS BAÑOS DE LIMPIEZA Y EN OPERACIONES DE GALVANOPLASTIA DONDE LOS CIANUROS SON USADOS EN LOS PROCESOS','R,Tt','A4050'),
('NE 10','RESIDUOS DE LOS BAÑOS DE ACEITE EN LAS OPERACIONES DE TRATAMIENTO TERMICO DE METALES','R,Tt',null),
('NE 11','SOLUCIONES GASTADAS DE CIANUROS DE LA LIMPIEZA DE TANQUES DE BAÑOS DE SAL EN LAS OPERACIONES DE TRATAMIENTO TERMICO DE METALES','R,Tt','A4050'),
('NE 12','RESIDUOS GENERADOS EN LA PRODUCCION DE TRI-, TETRA- O PENTACLOROFENOL','Th',null),
('NE 13','RESIDUOS DE TETRA-, PENTA O HEXACLOROBENCENO PROVENIENTES DE SU USO COMO REACTANTE, PRODUCTO INTERMEDIO O COMPONENTE DE UNA FORMULACION, BAJO CONDICIONES ALCALINAS','Th',null),
('NE 14','RESIDUOS, EXCEPTO AGUAS RESIDUALES Y CARBON GASTADO DE LA PURIFICACION DE CLORURO DE HIDROGENO, DE LA PRODUCCION DE MATERIALES EN EQUIPOS PREVIAMENTE USADOS EN LA MANUFACTURA (COMO REACTIVO, PRODUCTO QUIMICO INTERMEDIO O COMPONENTE EN UN PROCESO DE FORMULACION) DE TRI- Y TETRACLOROFENOLES. ESTE RESIDUO NO INCLUYE DESECHOS DE EQUIPOS UTILIZADOS EN LA PRODUCCION O USO DE HEXACLOROFENO A PARTIR DEL 2,4,5-TRICLOROFENOL ALTAMENTE PURIFICADO','Th',null),
('NE 15','FONDOS LIGEROS CONDENSADOS, FILTROS GASTADOS Y FILTROS AYUDA Y RESIDUOS DE DESECANTE GASTADO DE LA PRODUCCION DE CIERTOS HIDROCARBUROS ALIFATICOS CLORADOS A TRAVES DE LOS PROCESOS CATALITICOS DE RADICALES LIBRES. ESTOS HIDROCARBUROS ALIFATICOS CLORADOS SON AQUELLOS CON CADENAS DE UNO HASTA CINCO CARBONOS Y QUE CONTIENEN CLORO EN CANTIDADES Y SUSTITUCIONES VARIADAS','Tt',null),
('NE 16','RESIDUOS DE LA PRODUCCION DE MATERIALES EN EQUIPOS PREVIAMENTE USADOS EN LA PRODUCCION O MANUFACTURA DE TETRA-, PENTA- O HEXACLOROBENCENOS (COMO REACTIVO, PRODUCTO QUIMICO INTERMEDIO O COMPONENTE EN UN PROCESO DE FORMULACION) BAJO CONDICIONES ALCALINAS, EXCEPTO AGUAS RESIDUALES Y CARBON GASTADO DE LA PURIFICACION DE CLORURO DE HIDROGENO','Th',null),
('NE 17','RESIDUALES DE PROCESO, FORMULACIONES GASTADAS DE PROCESOS DE PRESERVACION DE LA MADERA EN PLANTAS QUE UTILIZAN ACTUALMENTE O HAYAN UTILIZADO FORMULACIONES DE CLOROFENOL, EXCEPTO AQUELLOS QUE NO HAYAN ESTADO EN CONTACTO CON CONTAMINANTES DE PROCESO','Tt',null),
('NE 18','RESIDUALES DE PROCESO Y FORMULACIONES GASTADAS DE PROCESOS DE PRESERVACION DE LA MADERA EN PLANTAS QUE UTILICEN FORMULACIONES DE CREOSOTA, EXCEPTO AQUELLOS QUE NO HAYAN ESTADO EN CONTACTO CON CONTAMINANTES DE PROCESO','Tt',null),
('NE 19','RESIDUALES DE PROCESO Y FORMULACIONES GASTADAS DE PROCESOS DE PRESERVACION DE LA MADERA EN PLANTAS QUE UTILICEN FORMULACIONES INORGANICAS QUE CONTENGAN ARSENICO O CROMO PARA PRESERVAR LA MADERA, EXCEPTO AQUELLOS QUE NO HAYAN ESTADO EN CONTACTO CON CONTAMINANTES DE PROCESO','Tt',null),
('NE 20','LIXIVIADOS (LIQUIDOS QUE HAN PERCOLADO A TRAVES DE RESIDUOS DISPUESTOS EN TIERRA) RESULTANTES DE LA DISPOSICION DE UNO O MAS DE LOS RESIDUOS PELIGROSOS SEÑALADOS EN ESTA NORMA','Tt',null),
('NE 21','RESIDUOS RESULTANTES DE LA INCINERACION O DE TRATAMIENTO TERMICO DE SUELOS CONTAMINADOS CON LOS RESIDUOS PELIGROSOS CON CLAVES NE 12, NE 13, NE 14 Y NE 16','Tt',null)
) v(k,d,h,bc)
join public.legal_instruments i on i.code = 'NOM-052-SEMARNAT-2005'
on conflict (instrument_id, listing_code, entry_key) do nothing;
